static void emit_usage(void) {
    fprintf(stderr, "%s\nusage: %s [-bdeEfiIlmorsStTvVwW [args]] [+opt[=arg] ...] [file ...]\n",
            RELEASE_LINE, prog_name);
}

static void emit_error(const char *msg) {
    fprintf(stderr, "%s\n<%s>: \n%s\nprogram abnormally terminated\n",
            RELEASE_LINE, prog_name, msg);
}

static void set_prog_name(const char *argv0) {
    const char *base = strrchr(argv0, '/');
    static char buf[1024];
    if (base) base++;
    else base = argv0;
    strncpy(buf, base, sizeof(buf)-1);
    buf[sizeof(buf)-1] = '\0';
    prog_name = buf;
}

/* Parse geo-coordinate in degrees form like "2d30'00.00"E or plain float */
static int parse_coord(const char *s, double *val, char hemi_pos, char hemi_neg) {
    /* Returns 1 if ok; val in degrees */
    char *end;
    double d = 0.0, m = 0.0, sec = 0.0;
    int sign = 1;
    const char *p = s;
    while (isspace((unsigned char)*p)) p++;
    if (*p == '-') { sign = -1; p++; }
    else if (*p == '+') { p++; }
    d = strtod(p, &end);
    if (end == p) return 0;
    p = end;
    if (*p == 'd' || *p == 'D') {
        p++;
        m = strtod(p, &end);
        if (end != p) {
            p = end;
            if (*p == '\'') {
                p++;
                sec = strtod(p, &end);
                if (end != p) {
                    p = end;
                    if (*p == '"') p++;
                }
            }
        }
        double val_deg = d + m/60.0 + sec/3600.0;
        if (*p == hemi_pos || *p == tolower(hemi_pos)) { p++; }
        else if (*p == hemi_neg || *p == tolower(hemi_neg)) { sign = -sign; p++; }
        *val = sign * val_deg;
        return 1;
    }
    /* plain decimal degrees */
    if (*p == hemi_pos || *p == tolower(hemi_pos)) { p++; }
    else if (*p == hemi_neg || *p == tolower(hemi_neg)) { sign = -sign; p++; }
    *val = sign * d;
    return 1;
}

struct ellps {
    const char *name;
    double a;
    double rf;   /* 1/f; 0 if spherical b==a */
    double b;    /* if rf==0 and b given */
};

/* Very minimal set */
static struct ellps known_ellps[] = {
    {"GRS80", 6378137.0, 298.257222101, 0},
    {"WGS84", 6378137.0, 298.257223563, 0},
    {"sphere", 6370997.0, 0, 6370997.0},
    {NULL, 0, 0, 0}
};

struct proj_params {
    const char *proj;
    double lat_0, lon_0, lat_1, lat_2, lat_ts, k_0;
    double x_0, y_0;
    double a, b, es, e;
    double to_meter;
    int has_lat_ts;
    const char *units;
};

static void set_ellps(struct proj_params *pp, const char *name) {
    for (int i = 0; known_ellps[i].name; i++) {
        if (!strcmp(known_ellps[i].name, name)) {
            pp->a = known_ellps[i].a;
            if (known_ellps[i].rf > 0) {
                double f = 1.0 / known_ellps[i].rf;
                pp->b = pp->a * (1.0 - f);
            } else {
                pp->b = known_ellps[i].b;
            }
            double a = pp->a, b = pp->b;
            pp->es = (a*a - b*b) / (a*a);
            pp->e = sqrt(pp->es);
            return;
        }
    }
}

static void default_ellps(struct proj_params *pp) {
    set_ellps(pp, "GRS80");
}

/* Merc forward (elliptical) */
static int merc_fwd(struct proj_params *pp, double lam, double phi, double *x, double *y) {
    /* lam, phi in radians, from lon_0 */
    double a = pp->a;
    double e = pp->e;
    double k0 = pp->k_0;
    if (pp->has_lat_ts) {
        double cos_ts = cos(pp->lat_ts);
        double sin_ts = sin(pp->lat_ts);
        k0 = cos_ts / sqrt(1.0 - pp->es * sin_ts * sin_ts);
    }
    if (fabs(phi) >= M_PI/2.0 - 1e-15) return 0;
    double sinphi = sin(phi);
    double t;
    if (pp->es == 0.0) {
        /* spherical */
        t = tan(M_PI/4.0 + phi/2.0);
        *x = a * k0 * lam;
        *y = a * k0 * log(t);
    } else {
        double es = pp->es;
        double e = pp->e;
        t = tan(M_PI/4.0 + phi/2.0) * pow((1.0 - e*sinphi)/(1.0 + e*sinphi), e/2.0);
        *x = a * k0 * lam;
        *y = a * k0 * log(t);
    }
    return 1;
}

static int merc_inv(struct proj_params *pp, double x, double y, double *lam, double *phi) {
    double a = pp->a;
    double k0 = pp->k_0;
    if (pp->has_lat_ts) {
        double sin_ts = sin(pp->lat_ts);
        k0 = cos(pp->lat_ts) / sqrt(1.0 - pp->es * sin_ts * sin_ts);
    }
    *lam = x / (a * k0);
    double t = exp(-y / (a * k0));
    if (pp->es == 0.0) {
        *phi = M_PI/2.0 - 2.0 * atan(t);
    } else {
        double e = pp->e;
        double phi_est = M_PI/2.0 - 2.0 * atan(t);
        for (int i = 0; i < 15; i++) {
            double sp = sin(phi_est);
            double phi_new = M_PI/2.0 - 2.0 * atan(t * pow((1.0 - e*sp)/(1.0 + e*sp), e/2.0));
            if (fabs(phi_new - phi_est) < 1e-14) { phi_est = phi_new; break; }
            phi_est = phi_new;
        }
        *phi = phi_est;
    }
    return 1;
}

static void format_num(char *out, size_t sz, double v, const char *fmt) {
    snprintf(out, sz, fmt, v);
}

int main(int argc, char **argv) {
    set_prog_name(argv[0]);

    int inverse = 0;
    int verbose = 0;
    int bin_mode = 0;
    int ignore_bad = 0;
    int rad_mode_in = 0;
    int rad_mode_out = 0;
    int swap_input = 0;
    int swap_output = 0;
    const char *fmt = "%.2f";
    const char *err_str = "*";
    int fac_decimals = 2; /* -w */
    int fac_decimals_out = 2; /* -W */
    const char *output_file = NULL;
    const char *t_tag = NULL;
    int list_mode = 0;
    char list_sub = 0;

    struct proj_params pp;
    memset(&pp, 0, sizeof(pp));
    pp.k_0 = 1.0;
    pp.to_meter = 1.0;
    pp.units = NULL;

    int has_proj = 0;
    char proj_name[128] = {0};

    /* Collect file args */
    const char **files = calloc(argc+1, sizeof(char*));
    int nfiles = 0;

    for (int i = 1; i < argc; i++) {
        const char *a = argv[i];
        if (a[0] == '+') {
            /* Parse +key=val */
            const char *key = a+1;
            const char *eq = strchr(key, '=');
            char k[64], v[128];
            if (eq) {
                size_t kl = eq-key; if (kl > 63) kl = 63;
                memcpy(k, key, kl); k[kl] = 0;
                strncpy(v, eq+1, 127); v[127] = 0;
            } else {
                strncpy(k, key, 63); k[63] = 0; v[0] = 0;
            }
            if (!strcmp(k, "proj")) {
                has_proj = 1;
                strncpy(proj_name, v, sizeof(proj_name)-1);
            } else if (!strcmp(k, "ellps")) {
                set_ellps(&pp, v);
            } else if (!strcmp(k, "a")) {
                pp.a = atof(v);
            } else if (!strcmp(k, "b")) {
                pp.b = atof(v);
            } else if (!strcmp(k, "lat_0")) {
                pp.lat_0 = atof(v) * M_PI/180.0;
            } else if (!strcmp(k, "lon_0")) {
                pp.lon_0 = atof(v) * M_PI/180.0;
            } else if (!strcmp(k, "lat_1")) {
                pp.lat_1 = atof(v) * M_PI/180.0;
            } else if (!strcmp(k, "lat_2")) {
                pp.lat_2 = atof(v) * M_PI/180.0;
            } else if (!strcmp(k, "lat_ts")) {
                pp.lat_ts = atof(v) * M_PI/180.0;
                pp.has_lat_ts = 1;
            } else if (!strcmp(k, "k_0") || !strcmp(k, "k")) {
                pp.k_0 = atof(v);
            } else if (!strcmp(k, "x_0")) {
                pp.x_0 = atof(v);
            } else if (!strcmp(k, "y_0")) {
                pp.y_0 = atof(v);
            } else if (!strcmp(k, "to_meter")) {
                pp.to_meter = atof(v);
            } else if (!strcmp(k, "units")) {
                pp.units = strdup(v);
                if (!strcmp(v, "km")) pp.to_meter = 1000.0;
                else if (!strcmp(v, "m")) pp.to_meter = 1.0;
            }
            /* ignore unknown */
        } else if (a[0] == '-' && a[1]) {
            char c = a[1];
            switch (c) {
                case 'I': inverse = 1; break;
                case 'i': ignore_bad = 1; break;
                case 'V': verbose = 1; break;
                case 'v': /* verbose? */ break;
                case 'b': bin_mode = 1; break;
                case 'r': rad_mode_in = 1; break;
                case 's': swap_input = 1; break;
                case 'S': swap_output = 1; break;
                case 'E': /* echo input */ break;
                case 'l': {
                    list_mode = 1;
                    char sub = a[2];
                    if (sub == 0 || sub == 'p') { list_sub = 'p'; }
                    else if (sub == 'P') list_sub = 'P';
                    else if (sub == 'e') list_sub = 'e';
                    else if (sub == 'u') list_sub = 'u';
                    else {
                        char buf[64];
                        snprintf(buf, sizeof(buf), "invalid list option: %s", a+1);
                        emit_error(buf);
                        return 1;
                    }
                    break;
                }
                case 'f': {
                    const char *arg = a+2;
                    if (!*arg && i+1 < argc) { arg = argv[++i]; }
                    if (!*arg) {
                        emit_error("missing argument for -f");
                        return 1;
                    }
                    fmt = arg;
                    break;
                }
                case 'e': {
                    const char *arg = a+2;
                    if (!*arg && i+1 < argc) { arg = argv[++i]; }
                    if (!*arg) {
                        emit_error("missing argument for -e");
                        return 1;
                    }
                    err_str = arg;
                    break;
                }
                case 'd': {
                    const char *arg = a+2;
                    if (!*arg && i+1 < argc) { arg = argv[++i]; }
                    if (!*arg) {
                        emit_error("missing argument for -d");
                        return 1;
                    }
                    /* decimals on angular output */
                    break;
                }
                case 'm': {
                    const char *arg = a+2;
                    if (!*arg && i+1 < argc) { arg = argv[++i]; }
                    if (!*arg) {
                        emit_error("missing argument for -m");
                        return 1;
                    }
                    /* scale */
                    break;
                }
                case 'o': {
                    const char *arg = a+2;
                    if (!*arg && i+1 < argc) { arg = argv[++i]; }
                    if (!*arg) {
                        emit_error("missing argument for -o");
                        return 1;
                    }
                    output_file = arg;
                    break;
                }
                case 't': {
                    const char *arg = a+2;
                    if (!*arg) {
                        emit_error("missing -t col. 1 tag");
                        return 1;
                    }
                    t_tag = arg;
                    break;
                }
                case 'w': case 'W': {
                    const char *arg = a+2;
                    if (!*arg) {
                        emit_error("-W argument missing or non-digit");
                        return 1;
                    }
                    if (!isdigit((unsigned char)*arg)) {
                        emit_error("-W argument missing or non-digit");
                        return 1;
                    }
                    if (c == 'w') fac_decimals = atoi(arg);
                    else fac_decimals_out = atoi(arg);
                    break;
                }
                default: {
                    char buf[64];
                    snprintf(buf, sizeof(buf), "invalid option: -%c", c);
                    emit_error(buf);
                    return 1;
                }
            }
        } else {
            files[nfiles++] = a;
        }
    }

    if (list_mode) {
        if (list_sub == 'p') fputs(LIST_L, stdout);
        else if (list_sub == 'P') fputs(LIST_LP, stdout);
        else if (list_sub == 'e') fputs(LIST_LE, stdout);
        else if (list_sub == 'u') fputs(LIST_LU, stdout);
        return 0;
    }

    if (!has_proj && nfiles == 0 && isatty(0)) {
        emit_usage();
        return 0;
    }
    if (!has_proj) {
        /* Without +proj, nothing happens? */
        if (nfiles == 0) { emit_usage(); return 0; }
        /* With file args but no proj, it would error. */
        emit_usage();
        return 0;
    }

    /* Check for longlat-like proj which the tool rejects */
    if (!strcmp(proj_name, "longlat") || !strcmp(proj_name, "latlong") ||
        !strcmp(proj_name, "latlon") || !strcmp(proj_name, "lonlat")) {
        emit_error("can't initialize operations that produce angular output coordinates");
        return 1;
    }

    /* Initialize defaults */
    if (pp.a == 0) default_ellps(&pp);
    if (pp.b == 0 && pp.a != 0) pp.b = pp.a; /* sphere */
    if (pp.a != 0) {
        pp.es = (pp.a*pp.a - pp.b*pp.b) / (pp.a*pp.a);
        pp.e = sqrt(pp.es);
    }

    FILE *out = stdout;
    if (output_file) {
        out = fopen(output_file, "w");
        if (!out) {
            char buf[512];
            snprintf(buf, sizeof(buf), "Sys errno: %d: %s\ninput file: %s",
                     errno, strerror(errno), output_file);
            emit_error(buf);
            return 0;
        }
    }

    /* Open input sources */
    FILE **inputs;
    int ninputs = 0;
    if (nfiles == 0) {
        inputs = malloc(sizeof(FILE*));
        inputs[0] = stdin;
        ninputs = 1;
    } else {
        inputs = malloc(nfiles * sizeof(FILE*));
        for (int i = 0; i < nfiles; i++) {
            FILE *f = fopen(files[i], "r");
            if (!f) {
                char buf[512];
                snprintf(buf, sizeof(buf), "Sys errno: %d: %s\ninput file: %s",
                         errno, strerror(errno), files[i]);
                emit_error(buf);
                return 0;
            }
            inputs[ninputs++] = f;
        }
    }

    if (verbose) {
        /* Print verbose header for merc */
        if (!strcmp(proj_name, "merc")) {
            fprintf(out, "#Mercator\n#\tCyl, Sph&Ell\n#\tlat_ts=\n");
        }
        fprintf(out, "# +proj=%s +break_cs2cs_recursion +ellps=GRS80\n", proj_name);
        fprintf(out, "#Final Earth figure: ellipsoid\n");
        fprintf(out, "#  Major axis (a): %.3f\n", pp.a);
        if (pp.b && pp.a != pp.b) {
            double f = (pp.a - pp.b) / pp.a;
            fprintf(out, "#  1/flattening: %.6f\n", 1.0/f);
        }
        fprintf(out, "#  squared eccentricity: %.12f\n", pp.es);
    }

    for (int ii = 0; ii < ninputs; ii++) {
        FILE *in = inputs[ii];
        char line[4096];
        while (fgets(line, sizeof(line), in)) {
            /* Remove newline */
            size_t ll = strlen(line);
            int has_nl = 0;
            while (ll && (line[ll-1] == '\n' || line[ll-1] == '\r')) {
                line[--ll] = 0;
                has_nl = 1;
            }
            /* Comment handling */
            if (line[0] == '#') {
                if (!ignore_bad) fprintf(out, "%s\n", line);
                continue;
            }
            /* Parse two coordinates */
            char *p = line;
            /* Skip whitespace */
            while (*p && isspace((unsigned char)*p)) p++;
            if (!*p) {
                fprintf(out, "%s\n", "0.00\t0.00");
                continue;
            }
            char *save = p;
            double lon, lat;
            int ok1 = parse_coord(p, &lon, 'E', 'W');
            /* Advance past first token */
            while (*p && !isspace((unsigned char)*p)) p++;
            while (*p && isspace((unsigned char)*p)) p++;
            int ok2 = parse_coord(p, &lat, 'N', 'S');
            /* Advance past second token */
            while (*p && !isspace((unsigned char)*p)) p++;
            /* The rest is extra */
            const char *rest = p;
            if (swap_input) { double t = lon; lon = lat; lat = t; }

            if (rad_mode_in || inverse) {
                /* For inverse or radians, input might not be in degrees */
            }

            double xout, yout;
            if (inverse) {
                double xin = lon, yin = lat;
                merc_inv(&pp, xin, yin, &xout, &yout);
                /* Output as degrees */
                xout = xout * 180.0 / M_PI;
                yout = yout * 180.0 / M_PI;
                /* Format like "2dE   45dN" */
                char lonh = (xout >= 0) ? 'E' : 'W';
                char lath = (yout >= 0) ? 'N' : 'S';
                fprintf(out, "%gd%c\t%gd%c", fabs(xout), lonh, fabs(yout), lath);
                if (*rest) fputs(rest, out);
                fputc('\n', out);
            } else {
                if (!ok1) lon = 0;
                if (!ok2) lat = 0;
                double lam = (rad_mode_in ? lon : lon * M_PI / 180.0) - pp.lon_0;
                double phi = rad_mode_in ? lat : lat * M_PI / 180.0;
                merc_fwd(&pp, lam, phi, &xout, &yout);
                xout = (xout + pp.x_0) / pp.to_meter;
                yout = (yout + pp.y_0) / pp.to_meter;
                char b1[64], b2[64];
                format_num(b1, sizeof(b1), xout, fmt);
                format_num(b2, sizeof(b2), yout, fmt);
                fprintf(out, "%s\t%s", b1, b2);
                if (*rest) fputs(rest, out);
                fputc('\n', out);
            }
        }
    }

    return 0;
}
