/* Parse geo-coordinate in degrees form like "2d30'00.00"E or plain float */
static int parse_coord(const char *s, double *val, char hemi_pos, char hemi_neg) {
    /* Returns 1 if ok; val in degrees */
    char *end;
    double d = 0.0, m = 0.0, sec = 0.0;
    int sign = 1;
    const char *p = s;
    while (isspace((unsigned char)*p)) p++;
    if (*p == '-') { sign = -1; p++; }
    else if (*p == '+') { p++; }
    d = strtod(p, &end);
    if (end == p) return 0;
    p = end;
    if (*p == 'd' || *p == 'D') {
        p++;
        m = strtod(p, &end);
        if (end != p) {
            p = end;
            if (*p == '\'') {
                p++;
                sec = strtod(p, &end);
                if (end != p) {
                    p = end;
                    if (*p == '"') p++;
                }
            }
        }
        double val_deg = d + m/60.0 + sec/3600.0;
        if (*p == hemi_pos || *p == tolower(hemi_pos)) { p++; }
        else if (*p == hemi_neg || *p == tolower(hemi_neg)) { sign = -sign; p++; }
        *val = sign * val_deg;
        return 1;
    }
    /* plain decimal degrees */
    if (*p == hemi_pos || *p == tolower(hemi_pos)) { p++; }
    else if (*p == hemi_neg || *p == tolower(hemi_neg)) { sign = -sign; p++; }
    *val = sign * d;
    return 1;
}

struct ellps {
    const char *name;
    double a;
    double rf;   /* 1/f; 0 if spherical b==a */
    double b;    /* if rf==0 and b given */
};

/* Very minimal set */
static struct ellps known_ellps[] = {
    {"GRS80", 6378137.0, 298.257222101, 0},
    {"WGS84", 6378137.0, 298.257223563, 0},
    {"sphere", 6370997.0, 0, 6370997.0},
    {NULL, 0, 0, 0}
};

struct proj_params {
    const char *proj;
    double lat_0, lon_0, lat_1, lat_2, lat_ts, k_0;
    double x_0, y_0;
    double a, b, es, e;
    double to_meter;
    int has_lat_ts;
    const char *units;
};

static void set_ellps(struct proj_params *pp, const char *name) {
    for (int i = 0; known_ellps[i].name; i++) {
        if (!strcmp(known_ellps[i].name, name)) {
            pp->a = known_ellps[i].a;
            if (known_ellps[i].rf > 0) {
                double f = 1.0 / known_ellps[i].rf;
                pp->b = pp->a * (1.0 - f);
            } else {
                pp->b = known_ellps[i].b;
            }
            double a = pp->a, b = pp->b;
            pp->es = (a*a - b*b) / (a*a);
            pp->e = sqrt(pp->es);
            return;
        }
    }
}

static void default_ellps(struct proj_params *pp) {
    set_ellps(pp, "GRS80");
}

/* Merc forward (elliptical) */
static int merc_fwd(struct proj_params *pp, double lam, double phi, double *x, double *y) {
    /* lam, phi in radians, from lon_0 */
    double a = pp->a;
    double e = pp->e;
    double k0 = pp->k_0;
    if (pp->has_lat_ts) {
        double cos_ts = cos(pp->lat_ts);
        double sin_ts = sin(pp->lat_ts);
        k0 = cos_ts / sqrt(1.0 - pp->es * sin_ts * sin_ts);
    }
    if (fabs(phi) >= M_PI/2.0 - 1e-15) return 0;
    double sinphi = sin(phi);
    double t;
    if (pp->es == 0.0) {
        /* spherical */
        t = tan(M_PI/4.0 + phi/2.0);
        *x = a * k0 * lam;
        *y = a * k0 * log(t);
    } else {
        double es = pp->es;
        double e = pp->e;
        t = tan(M_PI/4.0 + phi/2.0) * pow((1.0 - e*sinphi)/(1.0 + e*sinphi), e/2.0);
        *x = a * k0 * lam;
        *y = a * k0 * log(t);
    }
    return 1;
}

static int merc_inv(struct proj_params *pp, double x, double y, double *lam, double *phi) {
    double a = pp->a;
    double k0 = pp->k_0;
    if (pp->has_lat_ts) {
        double sin_ts = sin(pp->lat_ts);
        k0 = cos(pp->lat_ts) / sqrt(1.0 - pp->es * sin_ts * sin_ts);
    }
    *lam = x / (a * k0);
    double t = exp(-y / (a * k0));
    if (pp->es == 0.0) {
        *phi = M_PI/2.0 - 2.0 * atan(t);
    } else {
        double e = pp->e;
        double phi_est = M_PI/2.0 - 2.0 * atan(t);
        for (int i = 0; i < 15; i++) {
            double sp = sin(phi_est);
            double phi_new = M_PI/2.0 - 2.0 * atan(t * pow((1.0 - e*sp)/(1.0 + e*sp), e/2.0));
            if (fabs(phi_new - phi_est) < 1e-14) { phi_est = phi_new; break; }
            phi_est = phi_new;
        }
        *phi = phi_est;
    }
    return 1;
}

static void format_num(char *out, size_t sz, double v, const char *fmt) {
    snprintf(out, sz, fmt, v);
