    /* Check for longlat-like proj which the tool rejects */
    if (!strcmp(proj_name, "longlat") || !strcmp(proj_name, "latlong") ||
        !strcmp(proj_name, "latlon") || !strcmp(proj_name, "lonlat")) {
        emit_error("can't initialize operations that produce angular output coordinates");
        return 1;
    }

    /* Initialize defaults */
    if (pp.a == 0) default_ellps(&pp);
    if (pp.b == 0 && pp.a != 0) pp.b = pp.a; /* sphere */
    if (pp.a != 0) {
        pp.es = (pp.a*pp.a - pp.b*pp.b) / (pp.a*pp.a);
        pp.e = sqrt(pp.es);
    }

    FILE *out = stdout;
    if (output_file) {
        out = fopen(output_file, "w");
        if (!out) {
            char buf[512];
            snprintf(buf, sizeof(buf), "Sys errno: %d: %s\ninput file: %s",
                     errno, strerror(errno), output_file);
            emit_error(buf);
            return 0;
        }
    }

    /* Open input sources */
    FILE **inputs;
    int ninputs = 0;
    if (nfiles == 0) {
        inputs = malloc(sizeof(FILE*));
        inputs[0] = stdin;
        ninputs = 1;
    } else {
        inputs = malloc(nfiles * sizeof(FILE*));
        for (int i = 0; i < nfiles; i++) {
            FILE *f = fopen(files[i], "r");
            if (!f) {
                char buf[512];
                snprintf(buf, sizeof(buf), "Sys errno: %d: %s\ninput file: %s",
                         errno, strerror(errno), files[i]);
                emit_error(buf);
                return 0;
            }
            inputs[ninputs++] = f;
        }
    }

    if (verbose) {
        /* Print verbose header for merc */
        if (!strcmp(proj_name, "merc")) {
            fprintf(out, "#Mercator\n#\tCyl, Sph&Ell\n#\tlat_ts=\n");
        }
        fprintf(out, "# +proj=%s +break_cs2cs_recursion +ellps=GRS80\n", proj_name);
        fprintf(out, "#Final Earth figure: ellipsoid\n");
        fprintf(out, "#  Major axis (a): %.3f\n", pp.a);
        if (pp.b && pp.a != pp.b) {
            double f = (pp.a - pp.b) / pp.a;
            fprintf(out, "#  1/flattening: %.6f\n", 1.0/f);
        }
        fprintf(out, "#  squared eccentricity: %.12f\n", pp.es);
    }

    for (int ii = 0; ii < ninputs; ii++) {
        FILE *in = inputs[ii];
        char line[4096];
        while (fgets(line, sizeof(line), in)) {
            /* Remove newline */
            size_t ll = strlen(line);
            int has_nl = 0;
            while (ll && (line[ll-1] == '\n' || line[ll-1] == '\r')) {
                line[--ll] = 0;
                has_nl = 1;
            }
            /* Comment handling */
            if (line[0] == '#') {
                if (!ignore_bad) fprintf(out, "%s\n", line);
                continue;
            }
            /* Parse two coordinates */
            char *p = line;
            /* Skip whitespace */
            while (*p && isspace((unsigned char)*p)) p++;
            if (!*p) {
                fprintf(out, "%s\n", "0.00\t0.00");
                continue;
            }
            char *save = p;
            double lon, lat;
            int ok1 = parse_coord(p, &lon, 'E', 'W');
            /* Advance past first token */
            while (*p && !isspace((unsigned char)*p)) p++;
            while (*p && isspace((unsigned char)*p)) p++;
            int ok2 = parse_coord(p, &lat, 'N', 'S');
            /* Advance past second token */
            while (*p && !isspace((unsigned char)*p)) p++;
            /* The rest is extra */
            const char *rest = p;
            if (swap_input) { double t = lon; lon = lat; lat = t; }

            if (rad_mode_in || inverse) {
                /* For inverse or radians, input might not be in degrees */
            }

            double xout, yout;
            if (inverse) {
                double xin = lon, yin = lat;
                merc_inv(&pp, xin, yin, &xout, &yout);
                /* Output as degrees */
                xout = xout * 180.0 / M_PI;
                yout = yout * 180.0 / M_PI;
                /* Format like "2dE   45dN" */
                char lonh = (xout >= 0) ? 'E' : 'W';
                char lath = (yout >= 0) ? 'N' : 'S';
                fprintf(out, "%gd%c\t%gd%c", fabs(xout), lonh, fabs(yout), lath);
                if (*rest) fputs(rest, out);
                fputc('\n', out);
            } else {
                if (!ok1) lon = 0;
                if (!ok2) lat = 0;
                double lam = (rad_mode_in ? lon : lon * M_PI / 180.0) - pp.lon_0;
                double phi = rad_mode_in ? lat : lat * M_PI / 180.0;
                merc_fwd(&pp, lam, phi, &xout, &yout);
                xout = (xout + pp.x_0) / pp.to_meter;
                yout = (yout + pp.y_0) / pp.to_meter;
                char b1[64], b2[64];
                format_num(b1, sizeof(b1), xout, fmt);
                format_num(b2, sizeof(b2), yout, fmt);
                fprintf(out, "%s\t%s", b1, b2);
                if (*rest) fputs(rest, out);
                fputc('\n', out);
            }
        }
    }

    return 0;
}
